#include <stdio.h>
#include <stdlib.h>
#include <string.h>

int main(void)
{
    int a[] = {10, 7, 8, 12};
    int i = 3;
    while (i > 0) {
        int p = (i - 1) / 2;
        if (a[p] >= a[i]) {
            break;
        }
        int t = a[p];
        a[p] = a[i];
        a[i] = t;
        i = p;
    }
    printf("%d\n", a[0]);
    return 0;
}

